<?php

namespace Agent\AgentBundle\Repository;
Use Doctrine\ORM\Query\Expr\Join;
/**
 * InterimairRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class InterimaireRepository extends \Doctrine\ORM\EntityRepository {

    public function gestion_menu($interimaire = null) {
        $now = new \DateTime();
        
        $qb = $this->getEntityManager()->createQueryBuilder()
                ->select("i ")
                ->from('AgentBundle:Interimaire', 'i')
                ->where('i.etatcloture In (0,1) and i.interimaire=:interimaire')
                ->andWhere(':now between i.datedebut and i.datefin')
                ->setParameter('interimaire', $interimaire)
                ->setParameter('now', $now->setTime(0, 0, 0));

        return $qb->getQuery()->getResult();
    }

    public function controle_etatinterim($interimaire = null, $interime = null, $control = null) {
        $now = new \DateTime();
        $retour = false;

        $qb = $this->getEntityManager()->createQueryBuilder()
                ->select("i ")
                ->from('AgentBundle:Interimaire', 'i')
                ->where('1=1 And i.etatcloture In (0,1)');
        if (!empty($control)) {
            $qb = $qb->andWhere('i.datedebut >= :now ');
        } else {
            $qb = $qb->where('i.interimaire=:interimaire')
                    ->andWhere(':now between i.datedebut and i.datefin')
                    ->setParameter('interimaire', $interimaire);
        }
        if (!empty($interime)) {
            $qb = $qb->andWhere('i.interime=:interime')
                    ->setParameter('interime', $interime);
        }


        $qb = $qb->setParameter('now', $now->setTime(0, 0, 0));

        //dump($qb->getQuery());die;
        $exe = $qb->getQuery()->getResult();

        //dump($exe);die;
        if (count($exe) > 0) {
            $retour = true;
        }
        return $retour;
    }

    public function interimDgEncours(){

         $now = new \DateTime();
          $qb =$this->createQueryBuilder('i')
          ->leftJoin('i.interime','a')
          ->where(':now between i.datedebut and i.datefin and i.etatcloture=0')
          ->andWhere('a.Fonction = 10')
          ->setParameter('now', $now->setTime(0, 0, 0));
         //dump($qb->getQuery()->getOneOrNullResult());
          //die;
          return $qb->getQuery()->getOneOrNullResult();
    }

    public function interimEncours($now){
         //$now = new \DateTime();
          $qb =$this->createQueryBuilder('i')
          ->leftJoin('i.interime','a')
          ->where(':now between i.datedebut and i.datefin')
          ->andWhere('a.Fonction <> 10')//Pas interim de DG
          ->andWhere('a.Direction = 3 and a.Fonction= 5')//Respnsable des Ressources Hummainnes
          ->setParameter('now', $now->setTime(0, 0, 0));
          return $qb->getQuery()->getOneOrNullResult();
    }
}
